style.css:
@-moz-document regexp(".*roblox\.com.*") {
html, body {
        background: url("https://media.giphy.com/media/ICOgUNjpvO0PC/giphy.gif") center/cover no-repeat fixed !important;
    }

    /* Remove Roblox backgrounds */
    * {
        background-color: transparent !important;
    }

    /* Header */
    .rbx-header {
        background-color: #FFB7D5 !important;
    }

    /* Text */
    .text-name, .text-title, .font-header-2, h1, h2 {
        color: #ffb7d5 !important;
        text-shadow: 2px 2px 4px #000 !important;
    }
}
